Vars: PerBar(0), Gate(False);
PerBar = PerBar + 1;
If Close >= Open Then Begin
    If Time >= 930 Then Gate = True Else Gate = False;
End Else Gate = False;
If MarketPosition = 0 and Gate and PerBar mod 3 = 0 Then Buy ("LE_NEST") 1 contract next bar at market;
If MarketPosition = 1 and PerBar mod 4 = 0 Then Sell ("LX_NEST") next bar at market;

Vars: Initialized(0), PerBar(0);
Once Begin Initialized = BarNumber; End;
PerBar = PerBar + 1;
If MarketPosition = 0 and Initialized = 1 and PerBar = 2 Then Buy ("LE_ONCE") 1 contract next bar at market;
If MarketPosition = 1 and PerBar = 6 Then Sell ("LX_ONCE") next bar at market;

Inputs: LoopLimit(3);
Vars: I(0), J(0), Total(0);
Total = 0;
For I = 1 To LoopLimit Begin Total = Total + I; End;
J = 0;
While J < LoopLimit Begin Total = Total + J; J = J + 1; End;
If MarketPosition = 0 and Total = 9 and BarNumber mod 4 = 1 Then Buy ("LE_LOOP") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 4 = 3 Then Sell ("LX_LOOP") next bar at market;

Vars: IntDiv(0), FloatDiv(0);
IntDiv = 5 / 2;
FloatDiv = 5.0 / 2.0;
If MarketPosition = 0 and IntDiv = FloatDiv and BarNumber mod 3 = 1 Then Buy ("LE_DIV") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 3 = 0 Then Sell ("LX_DIV") next bar at market;

Vars: Rounded(0), Boundary(0);
Rounded = 16777217 + BarNumber - BarNumber;
Boundary = 16777216;
If MarketPosition = 0 and Rounded = Boundary and BarNumber mod 3 = 1 Then Buy ("LE_F32") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 3 = 0 Then Sell ("LX_F32") next bar at market;

Vars: PriceSeries(0), Prior(0);
PriceSeries = Close;
Prior = PriceSeries[1];
If MarketPosition = 0 and BarNumber > 1 and Close >= Prior Then Buy ("LE_SER") 1 contract next bar at market;
If MarketPosition = 1 and Close < Prior Then Sell ("LX_SER") next bar at market;

Inputs: EntryEvery(3), ExitEvery(5), Offset(0.25);
Vars: Trigger(0);
Trigger = Close + Offset;
If MarketPosition = 0 and Trigger > Close and BarNumber mod EntryEvery = 0 Then Buy ("LE_INPUT") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod ExitEvery = 0 Then Sell ("LX_INPUT") next bar at market;

Vars: Extreme(0);
Extreme = Close + Close;
If MarketPosition = 0 and Extreme > 340282350000000000000000000000000000000 Then Buy ("LE_OVF") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 2 = 0 Then Sell ("LX_OVF") next bar at market;

Vars: Twice(0), NotANumber(0);
Twice = Close + Close;
NotANumber = Twice - Twice;
If MarketPosition = 0 and NotANumber <> NotANumber Then Buy ("LE_NAN") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 2 = 0 Then Sell ("LX_NAN") next bar at market;

Vars: Denormal(0);
Denormal = Close / 2;
If MarketPosition = 0 and Close > 0 and Denormal = 0 Then Buy ("LE_DEN") 1 contract next bar at market;
If MarketPosition = 1 and BarNumber mod 2 = 0 Then Sell ("LX_DEN") next bar at market;
